#include "native/providers/moe_accumulator/sm121_matrix_remainder_group.h"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>

namespace matrix=qrt_sm121_compact_matrix_group;
namespace original=qrt_q1_moe_hawkeye;
namespace candidate=qrt_sm121_matrix_remainder_group;
int signed_word(uint16_t value){return value&0x8000u?int(value)-65536:int(value);}
std::vector<uint16_t> read(const char* path,size_t count){
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if(!f||f.tellg()!=std::streamoff(count*2u))throw std::runtime_error("capture extent");
    std::vector<uint16_t> x(count);f.seekg(0);f.read(reinterpret_cast<char*>(x.data()),count*2u);
    if(!f)throw std::runtime_error("capture read");return x;
}
int main(int argc,char** argv)try{
    if(argc!=4)throw std::runtime_error("Q K 7169|8192");
    const unsigned tokens=std::stoul(argv[3]);
    if(tokens!=7169u&&tokens!=8192u)throw std::runtime_error("shape");
    auto q=read(argv[1],7169u*4096u),k=read(argv[2],7169u*512u);
    for(auto pair:{std::make_pair(&q,4096u),std::make_pair(&k,512u)}){
        const auto initial=*pair.first;
        pair.first->insert(pair.first->end(),initial.begin(),initial.begin()+size_t(tokens-7169u)*pair.second);
    }
    uint64_t dots=0,eligible=0,groups=0,old_admitted=0,extra=0,fallback=0,unsupported_compact=0;
    for(unsigned sample=0;sample<128u;++sample){
        const unsigned query=32u+sample*(tokens-33u)/127u;
        const unsigned prefix=(query/32u)*32u;
        for(unsigned head=0;head<16u;++head)for(unsigned key_sample=0;key_sample<32u;++key_sample){
            const unsigned key=key_sample*prefix/32u;
            const uint16_t* a=q.data()+(size_t(query)*16u+head)*256u;
            const uint16_t* b=k.data()+(size_t(key)*2u+head/8u)*256u;
            bool narrow=true;
            for(unsigned i=0;i<256u;++i)narrow&=qrt_sm121_narrow_f32_carry::eligible(a[i])&&qrt_sm121_narrow_f32_carry::eligible(b[i]);
            ++dots;if(!narrow)continue;++eligible;
            original::Value carry{0u,-133,false};float carried=0.0f;
            for(unsigned g=0;g<16u;++g){
                const auto pa=matrix::prepare(a+16u*g),pb=matrix::prepare(b+16u*g);
                original::Value terms[17];terms[0]=carry;int64_t mathematical=0;
                for(unsigned i=0;i<16u;++i){
                    terms[i+1u]=original::multiply_bf16(a[16u*g+i],b[16u*g+i],-133);
                    mathematical+=int64_t(signed_word(matrix::compact::word(pa.encoded,i)))*signed_word(matrix::compact::word(pb.encoded,i));
                }
                const auto expected=original::group_sum<26,-133>(terms,17u);
                const auto bits=matrix::f32::bits(original::value_to_float(expected));
                float old=matrix::f32::alignment::from_bits(0x4f395819u),value=old;
                const bool accepted_old=matrix::accumulate(carried,pa,pb,mathematical,&old);
                const bool accepted=candidate::accumulate(carried,pa,pb,mathematical,&value);
                if(accepted_old&&(!accepted||matrix::f32::bits(old)!=bits))throw std::runtime_error("old admission changed");
                if(accepted){
                    if(matrix::f32::bits(value)!=bits){
                        std::cerr<<"query="<<query<<" head="<<head<<" key="<<key<<" group="<<g<<'\n';
                        throw std::runtime_error("remainder carry differs");
                    }
                    if(accepted_old)++old_admitted;else ++extra;
                }else{
                    if(matrix::f32::bits(value)!=0x4f395819u)throw std::runtime_error("rejection changed output");
                    qrt_sm121_float_alignment::Group raw;
                    for(unsigned i=0;i<16u;++i)raw.set(i,a[16u*g+i],b[16u*g+i]);
                    value=qrt_sm121_narrow_f32_carry::accumulate(carried,raw);
                    if(matrix::f32::bits(value)!=bits)throw std::runtime_error("fallback carry differs");
                    ++fallback;
                    unsupported_compact+=!matrix::compact::unit(pa.encoded)||!matrix::compact::unit(pb.encoded);
                }
                carry=expected;carried=value;++groups;
            }
        }
    }
    std::cout<<"{\"kind\":\"captured_qk_matrix_remainder_host_sample\",\"tokens\":"<<tokens
        <<",\"source_capture_tokens\":7169,\"repeated_rows\":"<<tokens-7169u
        <<",\"query_samples\":128,\"heads\":16,\"keys_per_query_head\":32,\"sampled_dots\":"<<dots
        <<",\"domain_eligible_dots\":"<<eligible<<",\"ordered_groups\":"<<groups
        <<",\"original_matrix_admitted\":"<<old_admitted<<",\"additional_remainder_admitted\":"<<extra
        <<",\"original_narrow_fallback\":"<<fallback<<",\"unsupported_compact_row_groups\":"<<unsupported_compact
        <<",\"raw_carry_mismatches\":0,\"host_arithmetic_only\":true,\"gpu_executed\":false,\"inference_acceptance\":false}\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}
